def fibonacci(n):
    """
    Return the nth Fibonacci number.
    Assumes n is a non-negative integer.
    """
    if n < 0:
        return None
    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
